class WordDictionary{static class N{N[]c=new N[26];boolean end;}N r=new N();public WordDictionary(){}public void addWord(String s){N p=r;for(char x:s.toCharArray()){int k=x-'a';if(p.c[k]==null)p.c[k]=new N();p=p.c[k];}p.end=true;}boolean f(N p,String s,int i){if(p==null)return false;if(i==s.length())return p.end;if(s.charAt(i)=='.'){for(N x:p.c)if(f(x,s,i+1))return true;return false;}return f(p.c[s.charAt(i)-'a'],s,i+1);}public boolean search(String s){return f(r,s,0);}}
